window.LECCIONES = window.LECCIONES || {};
/* CSS: los ejemplos incluyen HTML + <style> para verse en vivo. v: 0 = sin vista previa. */
LECCIONES.css = { lang: 'css', capitulos: [
  { t: `Fundamentos`, d: `Cómo se aplica CSS, la sintaxis de una regla, la cascada y las unidades.`, secciones: [
    { n: `1.1`, t: `¿Qué es CSS y cómo se aplica?`, m: `4 min`,
      b: [`CSS (Cascading Style Sheets) decide cómo se ve el HTML: colores, tamaños, espacios y la colocación de cada elemento. El HTML dice qué es cada cosa; el CSS, cómo se presenta.`,
          `Hay tres formas de aplicarlo. La recomendada es un archivo externo enlazado con <link rel="stylesheet"> en el head, porque una sola hoja sirve para todas las páginas. También se puede escribir dentro de una etiqueta <style> en el head o directamente en un elemento con el atributo style, pero estas dos últimas mezclan diseño y contenido y son difíciles de mantener.`],
      k: [`Archivo externo: <link rel="stylesheet" href="css/styles.css">.`, `<style> en el head: útil para pruebas o una sola página.`, `Atributo style: solo para casos puntuales.`, `Una hoja externa se descarga una vez y la reutilizan todas las páginas.`],
      a: [[`<link rel="stylesheet">`, `Hoja externa. La forma profesional.`], [`<style>`, `CSS interno en el head del documento.`], [`style="…"`, `CSS en línea en un solo elemento. Tiene prioridad muy alta.`]], at: `Formas de añadir CSS`, ah: [`Forma`, `Cuándo usarla`],
      c: `<style>\n  h1 { color: #4F46E5; }\n  p { font-size: 18px; }\n</style>\n<h1>Festival DAW</h1>\n<p>Este texto tiene estilo desde la etiqueta style.</p>\n<p style="color: crimson;">Y este, desde el atributo style.</p>`,
      tip: `en vuestros proyectos, una carpeta css/ con un styles.css enlazado desde todas las páginas.` },
    { n: `1.2`, t: `Anatomía de una regla`, m: `3 min`,
      b: [`Una regla CSS tiene un selector, que indica a qué elementos se aplica, y un bloque de declaraciones entre llaves. Cada declaración es una pareja propiedad: valor terminada en punto y coma.`,
          `Si una propiedad o un valor están mal escritos, el navegador ignora esa declaración en silencio y sigue con la siguiente; no da error. Por eso las herramientas de desarrollo son clave: muestran tachadas las declaraciones que no se aplican.`],
      k: [`selector { propiedad: valor; }`, `Cada declaración termina en punto y coma.`, `Un error tipográfico se ignora sin avisar.`, `Comentarios: /* así */.`],
      a: [[`Selector`, `A qué elementos afecta: p, .tarjeta, #menu…`], [`Propiedad`, `Qué cambias: color, margin, display…`], [`Valor`, `Cómo lo cambias: red, 16px, flex…`], [`Declaración`, `propiedad: valor;`]], at: `Partes de una regla`, ah: [`Parte`, `Qué es`],
      c: `<style>\n  /* selector { propiedad: valor; } */\n  .aviso {\n    background: #FEF3C7;\n    color: #92400E;\n    padding: 12px;\n    border-radius: 8px;\n    colr: red; /* mal escrito: se ignora */\n  }\n</style>\n<p class="aviso">Las puertas abren a las 17:00.</p>`,
      e: `olvidar el punto y coma entre declaraciones. La siguiente línea se une a la anterior y ambas dejan de funcionar.`,
      tip: `en DevTools (F12 → Elements → Styles) podéis cambiar valores en directo y ver el efecto.` },
    { n: `1.3`, t: `Cascada, herencia y especificidad`, m: `6 min`,
      b: [`Cuando varias reglas afectan al mismo elemento, el navegador decide cuál gana en este orden: primero la importancia (!important), después la especificidad del selector y, si empatan, la que aparece más tarde en el código. Eso es la «cascada».`,
          `La especificidad se calcula contando: los ids pesan más que las clases, pseudoclases y atributos, y estos pesan más que las etiquetas. Un estilo en línea gana a casi todo. Además, algunas propiedades se heredan de padres a hijos (color, font-family, line-height…) y otras no (margin, border, background…).`],
      k: [`Orden: !important → especificidad → orden en el código.`, `Especificidad: id (1-0-0) > clase (0-1-0) > etiqueta (0-0-1).`, `color y font se heredan; margin y border no.`, `Evita !important: rompe la cascada y obliga a usar más !important.`],
      a: [[`p`, `0-0-1 · una etiqueta.`], [`.tarjeta p`, `0-1-1 · una clase y una etiqueta.`], [`#menu a:hover`, `1-1-1 · id, pseudoclase y etiqueta.`], [`style="…"`, `Estilo en línea: gana a los selectores.`], [`!important`, `Gana a todo lo anterior (úsalo casi nunca).`]], at: `Ejemplos de especificidad`, ah: [`Selector`, `Peso`],
      c: `<style>\n  p { color: gray; }\n  .destacado { color: green; }\n  #precio { color: crimson; }\n  p { color: blue; } /* más tarde, pero menos específica que .destacado */\n  .caja { color: #4F46E5; font-family: Georgia, serif; }\n</style>\n<p>Párrafo normal (azul: gana la última regla de p).</p>\n<p class="destacado">Con clase (verde).</p>\n<p class="destacado" id="precio">Con clase e id (rojo).</p>\n<div class="caja"><p>Este p tiene su propia regla de color (azul), pero hereda la fuente Georgia.</p><span>Este span hereda color y fuente de la caja.</span></div>`,
      e: `pensar que la última regla siempre gana. Solo gana si la especificidad empata.`,
      tip: `en DevTools, los estilos aparecen ordenados por especificidad y los que pierden salen tachados.`,
      q: { t: `¿Qué selector gana: .menu a o #principal a?`, o: [`.menu a`, `#principal a`, `El que esté más abajo`, `Ninguno`], ok: 1, why: `Un id pesa más que cualquier número de clases.` } },
    { n: `1.4`, t: `Unidades de medida`, m: `5 min`,
      b: [`Las unidades absolutas, como px, tienen siempre el mismo tamaño. Las relativas dependen de otra cosa: em, del tamaño de letra del elemento padre; rem, del tamaño de letra de la raíz (html, normalmente 16px); % del contenedor; y vw y vh, del ancho y alto de la ventana.`,
          `Para textos se recomienda rem: si el usuario aumenta la letra en su navegador, toda la web escala con él. Para anchos de cajas, % o fr en Grid. Para bordes finos, px.`],
      k: [`1rem = tamaño de letra del html (16px por defecto).`, `em se acumula al anidar; rem no.`, `100vw = todo el ancho de la ventana.`, `ch = ancho del carácter «0»: max-width: 65ch limita la línea de lectura.`],
      a: [[`px`, `Píxel. Fijo. Bordes, sombras, detalles.`], [`rem`, `Relativo a la letra del html. Textos y espacios.`], [`em`, `Relativo a la letra del padre.`], [`%`, `Porcentaje del contenedor.`], [`vw / vh`, `1 % del ancho / alto de la ventana.`], [`fr`, `Fracción del espacio libre (solo en Grid).`], [`ch`, `Ancho de un carácter. Ideal para max-width de textos.`]], at: `Unidades más usadas`, ah: [`Unidad`, `Qué mide`],
      c: `<style>\n  html { font-size: 16px; }\n  .rem { font-size: 1.5rem; }      /* 24px */\n  .padre { font-size: 20px; }\n  .em { font-size: 1.5em; }        /* 1.5 × 20 = 30px */\n  .ancho { width: 50%; background: #EEF0FF; }\n  .texto { max-width: 30ch; }\n</style>\n<p class="rem">1.5rem</p>\n<div class="padre"><p class="em">1.5em dentro de un padre de 20px</p></div>\n<div class="ancho">50 % del ancho</div>\n<p class="texto">Este párrafo nunca será más ancho de unos treinta caracteres, así que se lee cómodamente.</p>`,
      tip: `muchos proyectos ponen html { font-size: 100%; } y trabajan todo en rem.` }
  ]},
  { t: `Selectores`, d: `Elegir exactamente los elementos que quieres: clases, combinadores, atributos y pseudoclases.`, secciones: [
    { n: `2.1`, t: `Selectores básicos`, m: `4 min`,
      b: [`El selector de etiqueta (p) afecta a todos los elementos de ese tipo. El de clase (.tarjeta) a los que tienen esa clase, y es el más usado porque una clase se puede reutilizar. El de id (#menu) a un único elemento; mejor reservarlo para JavaScript y anclas.`,
          `Se pueden agrupar varios selectores separados por comas para darles el mismo estilo, y combinar etiqueta y clase sin espacio (p.aviso) para afinar más. El selector universal * afecta a todo.`],
      k: [`p → etiqueta · .clase → clase · #id → id.`, `h1, h2, h3 { } agrupa selectores.`, `p.aviso = párrafos que tienen la clase aviso.`, `Un elemento puede tener varias clases: class="btn grande".`],
      a: [[`*`, `Todos los elementos.`], [`p`, `Todos los párrafos.`], [`.btn`, `Elementos con class="btn".`], [`#menu`, `El elemento con id="menu".`], [`.btn.grande`, `Elementos con las dos clases a la vez.`], [`h1, h2`, `Grupo: h1 y h2.`]], at: `Selectores básicos`, ah: [`Selector`, `Selecciona`],
      c: `<style>\n  p { color: #374151; }\n  .btn { padding: 8px 14px; border-radius: 8px; background: #E5E7EB; border: 0; }\n  .btn.primario { background: #4F46E5; color: white; }\n  #titulo { letter-spacing: 2px; }\n  h1, h2 { font-family: Georgia, serif; }\n</style>\n<h1 id="titulo">Festival</h1>\n<h2>Entradas</h2>\n<p>Elige tu entrada:</p>\n<button class="btn">Día</button>\n<button class="btn primario">Abono</button>`,
      tip: `poned nombres de clase que digan qué es, no cómo se ve: .aviso mejor que .texto-amarillo.` },
    { n: `2.2`, t: `Combinadores`, m: `4 min`,
      b: [`Los combinadores seleccionan según la relación entre elementos. Un espacio (nav a) selecciona descendientes a cualquier profundidad. El símbolo > (ul > li) solo hijos directos. El + (h2 + p) el hermano que va justo después, y ~ (h2 ~ p) todos los hermanos posteriores.`,
          `Son útiles para dar estilo sin llenar el HTML de clases, pero un selector demasiado largo es frágil: si cambia la estructura, deja de funcionar.`],
      k: [`A B → B dentro de A (cualquier nivel).`, `A > B → B hijo directo de A.`, `A + B → B justo después de A.`, `A ~ B → todos los B hermanos posteriores a A.`],
      a: [[`nav a`, `Todos los enlaces dentro de nav.`], [`ul > li`, `Solo los li hijos directos de ul.`], [`h2 + p`, `El primer p después de un h2.`], [`h2 ~ p`, `Todos los p hermanos después de un h2.`]], at: `Combinadores`, ah: [`Selector`, `Selecciona`],
      c: `<style>\n  .menu a { color: #4F46E5; }\n  .lista > li { font-weight: bold; }\n  h2 + p { color: crimson; }\n</style>\n<nav class="menu"><a href="#">Inicio</a> · <span><a href="#">Cartel</a></span></nav>\n<ul class="lista">\n  <li>Hijo directo (negrita)\n    <ul><li>Nieto (sin negrita)</li></ul>\n  </li>\n</ul>\n<h2>Horarios</h2>\n<p>Este p va justo después del h2 (rojo).</p>\n<p>Este no.</p>`,
      tip: `intentad no pasar de tres niveles: .menu .item a ya es bastante.` },
    { n: `2.3`, t: `Selectores de atributo`, m: `3 min`,
      b: [`Seleccionan elementos según sus atributos: [type="email"] elige los inputs de correo, [href^="https"] los enlaces que empiezan por https, [href$=".pdf"] los que acaban en .pdf y [class*="btn"] los que contienen «btn».`,
          `Son muy prácticos en formularios y para marcar enlaces externos o descargas sin tocar el HTML.`],
      k: [`[attr] tiene el atributo.`, `[attr="v"] valor exacto.`, `^= empieza por · $= acaba en · *= contiene.`],
      a: [[`[disabled]`, `Elementos con el atributo disabled.`], [`[type="email"]`, `Inputs de tipo email.`], [`[href^="https"]`, `Enlaces que empiezan por https.`], [`[href$=".pdf"]`, `Enlaces que terminan en .pdf.`], [`[class*="col-"]`, `Clases que contienen «col-».`]], at: `Selectores de atributo`, ah: [`Selector`, `Selecciona`],
      c: `<style>\n  input[type="email"] { border: 2px solid #4F46E5; }\n  a[href$=".pdf"]::after { content: " (PDF)"; color: crimson; }\n  a[href^="https"] { font-style: italic; }\n</style>\n<input type="text" placeholder="Nombre">\n<input type="email" placeholder="Correo">\n<p><a href="normas.pdf">Normas</a> · <a href="https://mdn.dev">MDN</a></p>`,
      tip: `a[target="_blank"]::after { content: " ↗"; } avisa de que el enlace abre otra pestaña.` },
    { n: `2.4`, t: `Pseudoclases`, m: `5 min`,
      b: [`Las pseudoclases seleccionan elementos según su estado o su posición. Las de estado más usadas son :hover (ratón encima), :focus-visible (enfocado con teclado), :active (mientras se pulsa), :checked, :disabled, :valid e :invalid.`,
          `Las de posición permiten elegir el primero (:first-child), el último (:last-child) o patrones con :nth-child(): even para los pares, odd para los impares, 3n para uno de cada tres. :not() excluye elementos.`],
      k: [`:hover para ratón, :focus-visible para teclado: ¡pon los dos!`, `li:nth-child(even) → filas pares (tablas «cebra»).`, `:not(.activo) → todos menos los activos.`, `input:invalid se marca solo si no cumple required, pattern…`],
      a: [[`:hover`, `Ratón encima.`], [`:focus-visible`, `Enfocado con teclado (anillo de foco).`], [`:active`, `Mientras se hace clic.`], [`:checked`, `Checkbox o radio marcado.`], [`:disabled`, `Campo desactivado.`], [`:first-child / :last-child`, `Primer / último hijo.`], [`:nth-child(2n)`, `Uno de cada dos (pares).`], [`:not(sel)`, `Los que no cumplen el selector.`]], at: `Pseudoclases más usadas`, ah: [`Pseudoclase`, `Cuándo se aplica`],
      c: `<style>\n  .btn { padding: 10px 16px; background: #4F46E5; color: #fff; border: 0; border-radius: 8px; }\n  .btn:hover { background: #3730A3; }\n  .btn:focus-visible { outline: 3px solid #F59E0B; outline-offset: 2px; }\n  li:nth-child(even) { background: #F3F4F6; }\n  li:last-child { font-weight: bold; }\n  input:invalid { border-color: crimson; }\n</style>\n<button class="btn">Pasa el ratón o pulsa Tab</button>\n<ul><li>Uno</li><li>Dos</li><li>Tres</li><li>Cuatro</li></ul>\n<input type="email" value="esto no es un correo">`,
      e: `quitar el contorno de foco con outline: none sin poner otro. Quien navega con teclado deja de saber dónde está.`,
      tip: `pulsad Tab en el resultado para ver el estilo de :focus-visible.` },
    { n: `2.5`, t: `Pseudoelementos`, m: `4 min`,
      b: [`Los pseudoelementos permiten dar estilo a una parte de un elemento o crear contenido decorativo sin tocar el HTML. ::before y ::after insertan contenido antes o después (necesitan la propiedad content, aunque sea vacía).`,
          `::first-letter y ::first-line dan estilo a la primera letra o línea, ::placeholder al texto de ejemplo de un input, ::selection al texto seleccionado y ::marker a las viñetas de una lista.`],
      k: [`Se escriben con dos puntos dobles: ::before.`, `::before y ::after necesitan content.`, `Ideal para iconos y adornos, no para texto importante.`, `::marker cambia el color de las viñetas.`],
      a: [[`::before / ::after`, `Contenido decorativo antes / después.`], [`::first-letter`, `Primera letra (letra capital).`], [`::placeholder`, `Texto de ejemplo de un input.`], [`::selection`, `Texto seleccionado por el usuario.`], [`::marker`, `Viñeta o número de una lista.`]], at: `Pseudoelementos`, ah: [`Pseudoelemento`, `Qué selecciona`],
      c: `<style>\n  .nuevo::before { content: "★ "; color: #F59E0B; }\n  .cita::first-letter { font-size: 2.5em; float: left; line-height: 1; margin-right: 6px; color: #4F46E5; }\n  li::marker { color: crimson; }\n  input::placeholder { color: #9CA3AF; font-style: italic; }\n  ::selection { background: #FDE68A; }\n</style>\n<p class="nuevo">Novedad: abono VIP.</p>\n<p class="cita">Había una vez un festival creado por estudiantes de DAW que se convirtió en tradición.</p>\n<ul><li>Entrada</li><li>DNI</li></ul>\n<input placeholder="Escribe tu nombre">`,
      tip: `seleccionad texto del resultado para ver ::selection.` }
  ]},
  { t: `Color, texto y fondos`, d: `Formatos de color, tipografía, propiedades de texto, fondos, degradados y sombras.`, secciones: [
    { n: `3.1`, t: `Colores`, m: `4 min`,
      b: [`Un color se puede escribir con su nombre (red), en hexadecimal (#4F46E5), en rgb(79 70 229) o en hsl(243 75% 59%). HSL es el más fácil de ajustar a mano: tono (0-360), saturación y luminosidad.`,
          `Para transparencias se añade un cuarto valor: rgb(0 0 0 / 50%) o #00000080. La propiedad opacity también hace transparente un elemento, pero afecta a todo su contenido, texto incluido.`],
      k: [`#RRGGBB en hexadecimal; #RGB abreviado.`, `hsl(tono saturación luz) facilita crear variaciones.`, `/ 50% añade transparencia solo al color.`, `opacity afecta al elemento entero.`],
      a: [[`color`, `Color del texto.`], [`background-color`, `Color de fondo.`], [`#4F46E5`, `Hexadecimal.`], [`rgb(79 70 229 / 50%)`, `Rojo, verde, azul y transparencia.`], [`hsl(243 75% 59%)`, `Tono, saturación, luminosidad.`], [`currentColor`, `El mismo color que el texto.`], [`opacity: .5`, `Transparenta el elemento y su contenido.`]], at: `Color en CSS`, ah: [`Propiedad / valor`, `Qué hace`],
      c: `<style>\n  .a { background: #4F46E5; color: white; }\n  .b { background: hsl(243 75% 85%); }\n  .c { background: rgb(79 70 229 / 30%); }\n  .d { background: #4F46E5; color: white; opacity: .4; }\n  div { padding: 10px; margin: 6px 0; border-radius: 8px; }\n</style>\n<div class="a">Hexadecimal</div>\n<div class="b">HSL más claro (misma tonalidad)</div>\n<div class="c">Fondo con 30 % de opacidad</div>\n<div class="d">opacity: el texto también se transparenta</div>`,
      tip: `cambiad el último valor de hsl en el ejemplo para ver la misma tonalidad más clara u oscura.` },
    { n: `3.2`, t: `Tipografía`, m: `5 min`,
      b: [`font-family indica la fuente, con una lista de alternativas por si la primera no está disponible, terminando siempre en una familia genérica (sans-serif, serif, monospace). Para usar fuentes de Google Fonts se enlaza su CSS en el head y luego se nombra en font-family.`,
          `font-size controla el tamaño, font-weight el grosor (400 normal, 700 negrita), font-style la cursiva y line-height el interlineado, que para textos largos debería estar entre 1.4 y 1.7. El atajo font permite escribirlo todo en una línea.`],
      k: [`font-family: "Inter", Arial, sans-serif; (con alternativa final).`, `line-height sin unidad (1.6) escala con el tamaño de letra.`, `font-weight: 400 normal, 600 seminegrita, 700 negrita.`, `Google Fonts: <link> en el head + font-family.`],
      a: [[`font-family`, `Fuente y alternativas.`], [`font-size`, `Tamaño (mejor en rem).`], [`font-weight`, `Grosor: 100 a 900.`], [`font-style`, `normal o italic.`], [`line-height`, `Altura de línea (interlineado).`], [`font`, `Atajo: font: italic 700 1.2rem/1.5 Georgia, serif;`]], at: `Propiedades de fuente`, ah: [`Propiedad`, `Qué controla`],
      c: `<style>\n  body { font-family: Georgia, "Times New Roman", serif; }\n  h1 { font-family: Arial, Helvetica, sans-serif; font-weight: 800; font-size: 2rem; }\n  .largo { line-height: 1.7; font-size: 1.05rem; }\n  .corto { line-height: 1; }\n  code { font-family: "Courier New", monospace; }\n</style>\n<h1>Tipografía</h1>\n<p class="largo">Con line-height 1.7 un párrafo largo respira y se lee mucho mejor, sobre todo en pantallas pequeñas.</p>\n<p class="corto">Con line-height 1 las líneas quedan pegadas y cuesta seguir la lectura cuando el texto ocupa varias líneas.</p>\n<p>Comando: <code>git status</code></p>`,
      tip: `no uséis más de dos familias tipográficas por web: una para títulos y otra para texto.` },
    { n: `3.3`, t: `Propiedades de texto`, m: `4 min`,
      b: [`text-align alinea el texto (left, center, right, justify). text-decoration añade o quita subrayados; es la forma de quitar el subrayado a los enlaces. text-transform cambia mayúsculas y minúsculas sin tocar el HTML, y letter-spacing separa las letras.`,
          `Para textos que no caben, white-space: nowrap impide el salto de línea y text-overflow: ellipsis añade «…» (junto con overflow: hidden). word-break o overflow-wrap evitan que una palabra muy larga rompa el diseño.`],
      k: [`text-decoration: none quita el subrayado de los enlaces.`, `text-transform: uppercase pone el texto en mayúsculas.`, `Texto cortado con «…»: overflow hidden + white-space nowrap + text-overflow ellipsis.`, `text-shadow añade sombra al texto.`],
      a: [[`text-align`, `left, center, right, justify.`], [`text-decoration`, `underline, line-through, none.`], [`text-transform`, `uppercase, lowercase, capitalize.`], [`letter-spacing`, `Espacio entre letras.`], [`text-indent`, `Sangría de la primera línea.`], [`text-shadow`, `Sombra del texto: x y desenfoque color.`], [`text-overflow`, `ellipsis añade «…» al texto cortado.`]], at: `Propiedades de texto`, ah: [`Propiedad`, `Valores habituales`],
      c: `<style>\n  .centro { text-align: center; text-transform: uppercase; letter-spacing: 3px; }\n  a { text-decoration: none; color: #4F46E5; }\n  a:hover { text-decoration: underline; }\n  .corte { width: 200px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; border: 1px solid #ddd; }\n  .sombra { text-shadow: 2px 2px 4px rgb(0 0 0 / 30%); font-size: 1.6rem; }\n</style>\n<p class="centro">Cartel 2026</p>\n<p><a href="#">Enlace sin subrayado</a></p>\n<p class="corte">Este texto es demasiado largo para su caja y se corta con puntos suspensivos</p>\n<p class="sombra">Con sombra</p>`,
      tip: `justify en textos estrechos crea huecos feos entre palabras; en web suele ir mejor left.` },
    { n: `3.4`, t: `Fondos y degradados`, m: `5 min`,
      b: [`background-image pone una imagen de fondo; background-size: cover la escala para cubrir toda la caja y contain para que se vea entera. background-position la centra y background-repeat evita que se repita.`,
          `Los degradados son imágenes generadas por CSS: linear-gradient en una dirección y radial-gradient desde un centro. Se pueden poner varias capas de fondo separadas por comas, por ejemplo un degradado oscuro encima de una foto para que el texto se lea.`],
      k: [`background-size: cover → cubre sin deformar (puede recortar).`, `linear-gradient(135deg, color1, color2).`, `Varias capas: la primera de la lista queda encima.`, `Atajo: background: url(foto.jpg) center / cover no-repeat;`],
      a: [[`background-color`, `Color de fondo.`], [`background-image`, `url(…) o un degradado.`], [`background-size`, `cover, contain o medidas.`], [`background-position`, `center, top, 50% 20%…`], [`background-repeat`, `no-repeat, repeat-x…`], [`background-attachment`, `fixed: el fondo no se mueve al hacer scroll.`]], at: `Propiedades de fondo`, ah: [`Propiedad`, `Qué hace`],
      c: `<style>\n  .hero {\n    height: 160px; color: white; display: grid; place-items: center; border-radius: 12px;\n    background: linear-gradient(rgb(0 0 0 / 50%), rgb(0 0 0 / 50%)),\n                url(https://placehold.co/600x300/4F46E5/FFFFFF?text=Foto) center / cover no-repeat;\n  }\n  .grad { height: 60px; margin-top: 10px; border-radius: 12px; background: linear-gradient(90deg, #4F46E5, #EC4899); }\n  .radial { height: 60px; margin-top: 10px; border-radius: 12px; background: radial-gradient(circle, #FDE68A, #F59E0B); }\n</style>\n<div class="hero"><h2>Festival DAW</h2></div>\n<div class="grad"></div>\n<div class="radial"></div>`,
      tip: `para las cabeceras con foto del proyecto, el truco del degradado oscuro encima es el más usado.` },
    { n: `3.5`, t: `Bordes, esquinas y sombras`, m: `4 min`,
      b: [`border tiene tres partes: grosor, estilo (solid, dashed, dotted) y color, y se puede aplicar solo a un lado (border-bottom). border-radius redondea las esquinas; con 50 % en un cuadrado se obtiene un círculo.`,
          `box-shadow añade sombra a la caja: desplazamiento horizontal, vertical, desenfoque, extensión y color. Con inset la sombra va por dentro. outline es parecido al borde pero no ocupa espacio, por eso se usa para el anillo de foco.`],
      k: [`border: 2px solid #4F46E5;`, `border-radius: 50% → círculo (en un cuadrado).`, `box-shadow: 0 4px 12px rgb(0 0 0 / 15%);`, `outline no ocupa espacio ni mueve nada.`],
      a: [[`border`, `grosor estilo color.`], [`border-bottom`, `Solo el borde inferior.`], [`border-radius`, `Redondeo de esquinas.`], [`box-shadow`, `x y desenfoque extensión color.`], [`outline`, `Contorno exterior sin ocupar espacio.`], [`outline-offset`, `Separación del contorno.`]], at: `Bordes y sombras`, ah: [`Propiedad`, `Qué hace`],
      c: `<style>\n  .tarjeta { padding: 16px; border: 1px solid #E5E7EB; border-radius: 16px; box-shadow: 0 8px 24px rgb(0 0 0 / 12%); max-width: 260px; }\n  .avatar { width: 64px; height: 64px; border-radius: 50%; background: #4F46E5; }\n  .subrayado { border-bottom: 3px dashed #EC4899; display: inline-block; }\n</style>\n<div class="tarjeta">\n  <div class="avatar"></div>\n  <h3 class="subrayado">Banda A</h3>\n  <p>Viernes, 21:00</p>\n</div>`,
      tip: `sombras suaves y grandes (24px de desenfoque, poca opacidad) quedan mucho más modernas que las oscuras.` }
  ]},
  { t: `Modelo de caja y display`, d: `Content, padding, border y margin; box-sizing, tamaños, overflow y tipos de display.`, secciones: [
    { n: `4.1`, t: `El modelo de caja`, m: `5 min`,
      b: [`Todo elemento es una caja con cuatro capas, de dentro afuera: el contenido (content), el relleno interior (padding), el borde (border) y el margen exterior (margin). El padding comparte el fondo del elemento; el margin es transparente y separa la caja de las demás.`,
          `margin y padding aceptan de uno a cuatro valores: uno para todos los lados; dos para vertical y horizontal; cuatro en el sentido de las agujas del reloj (arriba, derecha, abajo, izquierda). margin: 0 auto centra horizontalmente una caja con ancho definido.`],
      k: [`content → padding → border → margin.`, `padding = dentro (con fondo); margin = fuera (transparente).`, `margin: 10px 20px → 10 arriba y abajo, 20 a los lados.`, `margin: 0 auto centra una caja con width.`],
      a: [[`padding: 10px`, `10px en los cuatro lados.`], [`padding: 10px 20px`, `Vertical 10, horizontal 20.`], [`padding: 5px 10px 15px 20px`, `Arriba, derecha, abajo, izquierda.`], [`margin-top`, `Solo el margen superior.`], [`margin: 0 auto`, `Centra horizontalmente un bloque con ancho.`]], at: `Valores de margin y padding`, ah: [`Valor`, `Significado`],
      c: `<style>\n  .caja {\n    width: 200px;\n    padding: 20px;\n    border: 6px solid #4F46E5;\n    margin: 20px auto;\n    background: #EEF0FF;\n  }\n</style>\n<div class="caja">Contenido. El fondo lila llega hasta el borde (incluye el padding). El margen de 20px es transparente y la caja está centrada.</div>`,
      tip: `en DevTools, la pestaña Computed dibuja el modelo de caja con cada medida.` },
    { n: `4.2`, t: `box-sizing`, m: `4 min`,
      b: [`Por defecto (content-box), width solo mide el contenido: si a una caja de 200px le añades 20px de padding y 5px de borde, ocupa 250px. Eso hace muy difícil cuadrar diseños.`,
          `Con box-sizing: border-box, width incluye el padding y el borde, así que la caja mide exactamente lo que dices. Casi todos los proyectos lo aplican a todos los elementos al principio de la hoja de estilos.`],
      k: [`content-box: width = solo contenido (por defecto).`, `border-box: width = contenido + padding + borde.`, `Ponlo al principio: *, *::before, *::after { box-sizing: border-box; }`],
      c: `<style>\n  .base { width: 200px; padding: 20px; border: 5px solid #4F46E5; margin-bottom: 10px; background: #EEF0FF; }\n  .content { box-sizing: content-box; }\n  .border { box-sizing: border-box; }\n</style>\n<div class="base content">content-box: mide 250px</div>\n<div class="base border">border-box: mide 200px</div>`,
      e: `poner width: 100% y padding a una caja sin border-box: se sale de su contenedor.`,
      tip: `empezad todos vuestros CSS con el reset de box-sizing; os ahorrará muchos dolores de cabeza.` },
    { n: `4.3`, t: `Tamaños y overflow`, m: `4 min`,
      b: [`width y height fijan el tamaño, pero en web conviene dejar que la altura dependa del contenido. min-width/max-width y min-height/max-height ponen límites: max-width: 100% en imágenes evita que se salgan de su contenedor, y max-width: 1200px con margin auto centra el contenido en pantallas grandes.`,
          `Cuando el contenido no cabe, overflow decide qué pasa: visible (se sale, por defecto), hidden (se recorta), scroll (siempre barra) o auto (barra solo si hace falta). aspect-ratio mantiene una proporción, por ejemplo 16 / 9 para vídeos.`],
      k: [`Evita height fijo en cajas con texto.`, `img { max-width: 100%; height: auto; }`, `overflow: auto añade scroll solo si hace falta.`, `aspect-ratio: 16 / 9 mantiene la proporción.`],
      a: [[`width / height`, `Ancho y alto.`], [`max-width`, `Ancho máximo (muy útil en responsive).`], [`min-height`, `Alto mínimo; deja crecer si hay más contenido.`], [`overflow`, `visible, hidden, scroll, auto.`], [`overflow-x / overflow-y`, `Solo en un eje.`], [`aspect-ratio`, `Proporción ancho / alto.`]], at: `Tamaño y desbordamiento`, ah: [`Propiedad`, `Qué hace`],
      c: `<style>\n  .contenedor { max-width: 320px; margin: 0 auto; }\n  .scroll { height: 70px; overflow: auto; border: 1px solid #ddd; padding: 8px; }\n  .video { aspect-ratio: 16 / 9; background: #111827; color: white; display: grid; place-items: center; margin-top: 10px; border-radius: 8px; }\n</style>\n<div class="contenedor">\n  <div class="scroll">Línea 1<br>Línea 2<br>Línea 3<br>Línea 4<br>Línea 5<br>Línea 6</div>\n  <div class="video">16:9</div>\n</div>`,
      tip: `la clase .contenedor { max-width: 1200px; margin-inline: auto; padding-inline: 16px; } aparece en casi todas las webs.` },
    { n: `4.4`, t: `display`, m: `5 min`,
      b: [`display define cómo se comporta una caja. block ocupa todo el ancho y empieza en línea nueva; inline se queda dentro del texto y no acepta width ni márgenes verticales; inline-block se queda en la línea pero sí acepta medidas. none oculta el elemento y lo quita del diseño.`,
          `flex y grid convierten el elemento en un contenedor que organiza a sus hijos (lo veréis en los próximos capítulos). Ocultar con visibility: hidden, en cambio, deja el hueco reservado.`],
      k: [`block, inline, inline-block, flex, grid, none.`, `display: none quita el elemento; visibility: hidden deja el hueco.`, `inline no acepta width ni margin vertical.`, `Para centrar algo en dos ejes: display: grid; place-items: center;`],
      a: [[`block`, `Nueva línea y todo el ancho (div, p, h1).`], [`inline`, `Dentro del texto; ignora width/height (span, a).`], [`inline-block`, `En línea pero con medidas (botones).`], [`flex`, `Contenedor flexible en una dimensión.`], [`grid`, `Contenedor en rejilla de dos dimensiones.`], [`none`, `Oculto y sin ocupar espacio.`]], at: `Valores de display`, ah: [`Valor`, `Comportamiento`],
      c: `<style>\n  span { background: #FDE68A; width: 200px; }  /* inline: ignora width */\n  .ib { display: inline-block; width: 120px; background: #C7D2FE; padding: 6px; }\n  .oculto { display: none; }\n  .invisible { visibility: hidden; }\n</style>\n<p>Texto con <span>un span</span> y <span class="ib">inline-block</span> dentro.</p>\n<p>Antes · <b class="oculto">display none</b> · Después</p>\n<p>Antes · <b class="invisible">visibility hidden</b> · Después</p>`,
      tip: `fijaos en el hueco que deja visibility: hidden en la última línea.` },
    { n: `4.5`, t: `Márgenes que colapsan y reset`, m: `4 min`,
      b: [`Cuando dos márgenes verticales se tocan (por ejemplo, el margin-bottom de un párrafo y el margin-top del siguiente), no se suman: se queda el mayor. Esto se llama colapso de márgenes y solo pasa en vertical y entre bloques.`,
          `Los navegadores aplican estilos por defecto (márgenes en body, h1, p, listas…), y cada uno los aplica un poco distinto. Por eso muchos proyectos empiezan con un pequeño reset que unifica la base.`],
      k: [`Dos márgenes verticales que se tocan: gana el mayor.`, `En flex y grid los márgenes no colapsan.`, `body tiene 8px de margen por defecto.`, `Un reset mínimo: box-sizing, margin 0 y imágenes responsive.`],
      c: `<style>\n  .a { margin-bottom: 30px; background: #EEF0FF; }\n  .b { margin-top: 20px; background: #FCE7F3; }\n  /* La separación es 30px, no 50px */\n</style>\n<p class="a">margin-bottom: 30px</p>\n<p class="b">margin-top: 20px → la separación real es 30px</p>`,
      o: `/* Reset mínimo recomendado */\n*, *::before, *::after { box-sizing: border-box; }\nbody { margin: 0; line-height: 1.5; }\nimg, video { max-width: 100%; height: auto; display: block; }\ninput, button, textarea, select { font: inherit; }`,
      tip: `copiad el reset de la salida al principio de vuestro styles.css.` }
  ]},
  { t: `Flexbox`, d: `Alinear y repartir elementos en una dimensión: ejes, justify, align, wrap y flex.`, secciones: [
    { n: `5.1`, t: `Contenedor flex y ejes`, m: `5 min`,
      b: [`Con display: flex en un contenedor, sus hijos directos pasan a ser elementos flexibles y se colocan en fila. Flexbox trabaja con dos ejes: el principal, que marca flex-direction (row por defecto, horizontal), y el cruzado, perpendicular a él.`,
          `flex-direction: column pone los elementos en columna, y entonces el eje principal pasa a ser el vertical. Entender qué eje es cuál es la clave de todo Flexbox: justify-content trabaja en el principal y align-items en el cruzado.`],
      k: [`display: flex afecta a los hijos directos.`, `row → eje principal horizontal; column → vertical.`, `justify-content = eje principal; align-items = eje cruzado.`, `gap separa los elementos sin márgenes.`],
      a: [[`display: flex`, `Activa Flexbox en el contenedor.`], [`flex-direction`, `row, row-reverse, column, column-reverse.`], [`gap`, `Espacio entre elementos.`], [`flex-wrap`, `wrap permite pasar a varias líneas.`]], at: `Propiedades del contenedor`, ah: [`Propiedad`, `Qué hace`],
      c: `<style>\n  .fila, .columna { display: flex; gap: 10px; padding: 10px; background: #F3F4F6; margin-bottom: 10px; }\n  .columna { flex-direction: column; }\n  .item { background: #4F46E5; color: white; padding: 10px 16px; border-radius: 8px; }\n</style>\n<div class="fila"><div class="item">1</div><div class="item">2</div><div class="item">3</div></div>\n<div class="columna"><div class="item">1</div><div class="item">2</div><div class="item">3</div></div>`,
      tip: `en DevTools aparece una etiqueta «flex» junto al contenedor: al pulsarla dibuja los ejes.` },
    { n: `5.2`, t: `justify-content y align-items`, m: `5 min`,
      b: [`justify-content reparte los elementos en el eje principal: al principio (flex-start), al final (flex-end), centrados (center) o con el espacio sobrante entre ellos (space-between, space-around, space-evenly).`,
          `align-items los alinea en el eje cruzado: stretch (los estira, por defecto), flex-start, center, flex-end o baseline (alinea la línea base del texto). Con justify-content: center y align-items: center se centra cualquier cosa en las dos direcciones.`],
      k: [`Centrar en dos ejes: justify-content: center + align-items: center.`, `space-between: primero y último pegados a los extremos.`, `align-items: stretch iguala las alturas.`, `align-self cambia la alineación de un solo hijo.`],
      a: [[`flex-start / flex-end`, `Al principio / final del eje.`], [`center`, `Centrado.`], [`space-between`, `Espacio entre elementos; nada en los extremos.`], [`space-around`, `Espacio alrededor de cada uno.`], [`space-evenly`, `Espacios exactamente iguales.`], [`stretch`, `(align-items) Estira en el eje cruzado.`], [`baseline`, `(align-items) Alinea la base del texto.`]], at: `Valores de alineación`, ah: [`Valor`, `Resultado`],
      c: `<style>\n  .barra { display: flex; justify-content: space-between; align-items: center; padding: 10px 16px; background: #111827; color: white; border-radius: 10px; }\n  .barra nav { display: flex; gap: 14px; }\n  .centro { display: flex; justify-content: center; align-items: center; height: 120px; background: #EEF0FF; margin-top: 10px; border-radius: 10px; }\n</style>\n<header class="barra">\n  <strong>Festival</strong>\n  <nav><a style="color:white">Cartel</a><a style="color:white">Entradas</a></nav>\n</header>\n<div class="centro"><b>Centrado en los dos ejes</b></div>`,
      tip: `la cabecera con logo a la izquierda y menú a la derecha es justo space-between.` },
    { n: `5.3`, t: `flex-grow, flex-shrink y flex-basis`, m: `5 min`,
      b: [`Estas propiedades se ponen en los hijos. flex-basis es el tamaño inicial del elemento; flex-grow indica cuánto crece para ocupar el espacio libre; flex-shrink, cuánto encoge cuando falta espacio.`,
          `El atajo flex las combina: flex: 1 hace que los elementos se repartan el espacio a partes iguales; flex: 2 en uno lo hace crecer el doble que los que tienen flex: 1; flex: none impide que crezca o encoja.`],
      k: [`flex: 1 → reparto a partes iguales.`, `flex: 0 0 200px → mide 200px fijos.`, `flex-grow solo reparte el espacio sobrante.`, `order cambia el orden visual (no el del HTML).`],
      a: [[`flex-grow`, `Cuánto crece (0 = nada).`], [`flex-shrink`, `Cuánto encoge (0 = nunca).`], [`flex-basis`, `Tamaño inicial antes de repartir.`], [`flex: 1`, `Atajo: crece y encoge igual que los demás.`], [`align-self`, `Alineación propia en el eje cruzado.`], [`order`, `Posición visual (por defecto 0).`]], at: `Propiedades de los hijos`, ah: [`Propiedad`, `Qué hace`],
      c: `<style>\n  .layout { display: flex; gap: 10px; height: 120px; }\n  .layout > div { padding: 10px; border-radius: 8px; color: white; }\n  .menu { flex: 0 0 120px; background: #374151; }\n  .principal { flex: 2; background: #4F46E5; }\n  .lateral { flex: 1; background: #EC4899; }\n</style>\n<div class="layout">\n  <div class="menu">120px fijos</div>\n  <div class="principal">flex: 2</div>\n  <div class="lateral">flex: 1</div>\n</div>`,
      tip: `cambiad el flex del principal a 1 y veréis cómo se igualan.` },
    { n: `5.4`, t: `flex-wrap y tarjetas`, m: `4 min`,
      b: [`Por defecto los elementos flex intentan caber en una sola línea y encogen. Con flex-wrap: wrap pasan a la línea siguiente cuando no caben, lo que permite hacer rejillas de tarjetas que se adaptan al ancho sin media queries.`,
          `Combinando flex-wrap con flex: 1 1 200px, cada tarjeta mide al menos 200px y crece para ocupar el hueco. Para rejillas más precisas, Grid suele ser mejor opción.`],
      k: [`flex-wrap: wrap → varias líneas.`, `flex: 1 1 200px → mínimo 200px y crece.`, `align-content reparte las líneas en el eje cruzado.`, `Flex = una dimensión; Grid = dos.`],
      c: `<style>\n  .tarjetas { display: flex; flex-wrap: wrap; gap: 10px; }\n  .tarjeta { flex: 1 1 140px; padding: 14px; background: #EEF0FF; border-radius: 10px; }\n</style>\n<div class="tarjetas">\n  <div class="tarjeta">Banda A</div>\n  <div class="tarjeta">Banda B</div>\n  <div class="tarjeta">Banda C</div>\n  <div class="tarjeta">Banda D</div>\n  <div class="tarjeta">Banda E</div>\n</div>`,
      tip: `jugad con el juego Flexbox Froggy (flexboxfroggy.com) para memorizar todas las propiedades.` },
    { n: `5.5`, t: `Patrones habituales con Flexbox`, m: `4 min`,
      b: [`Hay unos cuantos patrones que se repiten en todas las webs: la barra de navegación (space-between), el centrado perfecto, el pie de página pegado abajo (body en columna y main con flex: 1) y el «media object» (imagen a un lado y texto al otro).`,
          `margin-left: auto en un hijo flex empuja ese elemento y todos los siguientes al final: es la forma más sencilla de separar un botón del resto del menú.`],
      k: [`margin-left: auto empuja un elemento al final.`, `Footer abajo: body { display: flex; flex-direction: column; min-height: 100vh } main { flex: 1 }.`, `Media object: imagen con flex: none + texto con flex: 1.`],
      c: `<style>\n  nav { display: flex; gap: 12px; align-items: center; padding: 10px; background: #F3F4F6; border-radius: 10px; }\n  nav .login { margin-left: auto; background: #4F46E5; color: white; padding: 6px 12px; border-radius: 8px; }\n  .media { display: flex; gap: 12px; align-items: flex-start; margin-top: 12px; }\n  .media .foto { flex: none; width: 60px; height: 60px; border-radius: 50%; background: #EC4899; }\n</style>\n<nav><b>Logo</b><a>Cartel</a><a>Entradas</a><a class="login">Entrar</a></nav>\n<div class="media"><div class="foto"></div><p>Ana: «El mejor festival del año, repetiré seguro». El texto ocupa el resto del espacio.</p></div>`,
      tip: `estos tres patrones resuelven la mayoría de maquetaciones de un proyecto de clase.` }
  ]},
  { t: `CSS Grid`, d: `Rejillas en dos dimensiones: columnas con fr, colocar elementos, áreas y auto-fit.`, secciones: [
    { n: `6.1`, t: `Crear una rejilla`, m: `5 min`,
      b: [`Con display: grid y grid-template-columns defines las columnas de la rejilla, y los hijos se colocan automáticamente en ellas, fila a fila. La unidad fr reparte el espacio libre en fracciones: 1fr 2fr hace que la segunda columna mida el doble que la primera.`,
          `repeat() evita repetir valores: repeat(3, 1fr) son tres columnas iguales. Las filas se crean solas según haga falta, pero también se pueden definir con grid-template-rows. gap separa filas y columnas.`],
      k: [`grid-template-columns: 200px 1fr → columna fija + resto.`, `repeat(3, 1fr) → tres columnas iguales.`, `fr reparte el espacio libre.`, `gap: 16px separa filas y columnas.`],
      a: [[`display: grid`, `Activa Grid en el contenedor.`], [`grid-template-columns`, `Define las columnas.`], [`grid-template-rows`, `Define las filas.`], [`gap / row-gap / column-gap`, `Separación entre celdas.`], [`repeat(n, tamaño)`, `Repite una medida.`], [`minmax(min, max)`, `Tamaño entre un mínimo y un máximo.`]], at: `Propiedades del contenedor`, ah: [`Propiedad`, `Qué hace`],
      c: `<style>\n  .grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 10px; }\n  .grid div { background: #4F46E5; color: white; padding: 16px; border-radius: 8px; text-align: center; }\n  .dos { display: grid; grid-template-columns: 1fr 2fr; gap: 10px; margin-top: 10px; }\n  .dos div { background: #EC4899; color: white; padding: 16px; border-radius: 8px; }\n</style>\n<div class="grid"><div>1</div><div>2</div><div>3</div><div>4</div><div>5</div><div>6</div></div>\n<div class="dos"><div>1fr</div><div>2fr</div></div>`,
      tip: `en DevTools, la etiqueta «grid» dibuja las líneas numeradas de la rejilla.` },
    { n: `6.2`, t: `Colocar elementos`, m: `5 min`,
      b: [`Las líneas de la rejilla están numeradas desde 1. Con grid-column: 1 / 3 un elemento ocupa desde la línea 1 hasta la 3, es decir, dos columnas. span es más cómodo: grid-column: span 2 ocupa dos columnas desde donde le toque.`,
          `Lo mismo funciona con grid-row para ocupar varias filas. La línea -1 es siempre la última, así que grid-column: 1 / -1 ocupa todo el ancho.`],
      k: [`grid-column: 1 / 3 → de la línea 1 a la 3 (dos columnas).`, `grid-column: span 2 → ocupa dos columnas.`, `1 / -1 → todo el ancho.`, `Los elementos sin posición se colocan solos en los huecos.`],
      a: [[`grid-column`, `Columnas que ocupa: inicio / fin.`], [`grid-row`, `Filas que ocupa: inicio / fin.`], [`span n`, `Ocupa n celdas.`], [`-1`, `Última línea de la rejilla.`], [`grid-area`, `Nombre de área o fila / columna / fila / columna.`]], at: `Colocar hijos`, ah: [`Propiedad`, `Uso`],
      c: `<style>\n  .galeria { display: grid; grid-template-columns: repeat(4, 1fr); grid-auto-rows: 70px; gap: 8px; }\n  .galeria div { background: #C7D2FE; border-radius: 8px; display: grid; place-items: center; }\n  .grande { grid-column: span 2; grid-row: span 2; background: #4F46E5 !important; color: white; }\n  .ancha { grid-column: 1 / -1; background: #FBCFE8 !important; }\n</style>\n<div class="galeria">\n  <div class="grande">2×2</div><div>a</div><div>b</div><div>c</div><div>d</div>\n  <div class="ancha">Todo el ancho</div>\n</div>`,
      tip: `una galería así, con una foto grande destacada, queda genial en el proyecto.` },
    { n: `6.3`, t: `Áreas con nombre`, m: `5 min`,
      b: [`grid-template-areas permite dibujar la maqueta con nombres: cada cadena es una fila y cada palabra una celda. Luego, cada hijo se asigna a su zona con grid-area. Un punto (.) deja una celda vacía.`,
          `Es la forma más legible de hacer la estructura general de una página (cabecera, menú, contenido, lateral y pie), y para adaptarla al móvil basta con redibujar las áreas dentro de una media query.`],
      k: [`Cada cadena = una fila; cada palabra = una celda.`, `grid-area: nombre asigna el hijo a su zona.`, `Las áreas deben formar rectángulos.`, `En móvil, se redibuja el mapa en una media query.`],
      c: `<style>\n  .pagina {\n    display: grid; gap: 8px; height: 220px;\n    grid-template-columns: 120px 1fr;\n    grid-template-rows: auto 1fr auto;\n    grid-template-areas:\n      "cabecera cabecera"\n      "menu     contenido"\n      "pie      pie";\n  }\n  .pagina > * { padding: 10px; border-radius: 8px; color: white; }\n  header { grid-area: cabecera; background: #111827; }\n  nav { grid-area: menu; background: #374151; }\n  main { grid-area: contenido; background: #4F46E5; }\n  footer { grid-area: pie; background: #6B7280; }\n</style>\n<div class="pagina"><header>Cabecera</header><nav>Menú</nav><main>Contenido</main><footer>Pie</footer></div>`,
      tip: `cambiad las áreas en el ejemplo para poner el menú a la derecha.` },
    { n: `6.4`, t: `Rejillas automáticas: auto-fit y minmax`, m: `5 min`,
      b: [`La combinación repeat(auto-fit, minmax(200px, 1fr)) crea tantas columnas como quepan, cada una de al menos 200px, y las estira para llenar la fila. El resultado es una rejilla responsive sin una sola media query.`,
          `auto-fill hace algo parecido, pero mantiene las columnas vacías si sobra espacio en lugar de estirar las existentes. grid-auto-rows define la altura de las filas creadas automáticamente.`],
      k: [`repeat(auto-fit, minmax(200px, 1fr)) → rejilla responsive.`, `auto-fit estira las columnas; auto-fill deja huecos.`, `grid-auto-rows: 150px → altura de filas automáticas.`],
      c: `<style>\n  .cartel { display: grid; grid-template-columns: repeat(auto-fit, minmax(120px, 1fr)); gap: 10px; }\n  .cartel div { background: #EEF0FF; padding: 20px 10px; border-radius: 10px; text-align: center; }\n</style>\n<div class="cartel">\n  <div>Banda A</div><div>Banda B</div><div>Banda C</div><div>Banda D</div><div>Banda E</div>\n</div>\n<p><small>Estrecha o ensancha la ventana: las columnas se reorganizan solas.</small></p>`,
      tip: `es exactamente la rejilla que usa DevPath para las tarjetas de temas.` },
    { n: `6.5`, t: `Alinear en Grid`, m: `4 min`,
      b: [`Grid usa las mismas ideas de alineación que Flexbox. justify-items alinea el contenido de cada celda en horizontal y align-items en vertical. place-items es el atajo de ambas: place-items: center centra todo.`,
          `justify-content y align-content mueven la rejilla entera dentro del contenedor cuando sobra espacio. En un hijo concreto se usan justify-self y align-self.`],
      k: [`place-items: center → centra el contenido de las celdas.`, `justify-* = horizontal; align-* = vertical.`, `*-items para todas las celdas; *-self para una.`],
      a: [[`justify-items`, `Horizontal dentro de cada celda.`], [`align-items`, `Vertical dentro de cada celda.`], [`place-items`, `Atajo: align-items + justify-items.`], [`justify-content`, `Mueve toda la rejilla en horizontal.`], [`justify-self / align-self`, `Alineación de un solo hijo.`]], at: `Alineación en Grid`, ah: [`Propiedad`, `Qué alinea`],
      c: `<style>\n  .g { display: grid; grid-template-columns: repeat(3, 100px); grid-auto-rows: 80px; gap: 8px; place-items: center; background: #F3F4F6; padding: 8px; border-radius: 10px; }\n  .g div { background: #4F46E5; color: white; padding: 6px 10px; border-radius: 6px; }\n  .g .esquina { justify-self: end; align-self: end; background: #EC4899; }\n</style>\n<div class="g"><div>A</div><div>B</div><div class="esquina">C</div><div>D</div></div>`,
      tip: `practicad con Grid Garden (cssgridgarden.com).` }
  ]},
  { t: `Diseño responsive`, d: `Mobile first, media queries, tamaños fluidos y container queries.`, secciones: [
    { n: `7.1`, t: `Mobile first y la meta viewport`, m: `4 min`,
      b: [`Diseño responsive significa que la web se adapta a cualquier pantalla. El primer requisito está en el HTML: la meta viewport, sin la cual el móvil muestra la página como si fuera un escritorio en miniatura.`,
          `La estrategia «mobile first» consiste en escribir primero los estilos para móvil (una columna, sencillo) y añadir después, con media queries de min-width, los cambios para pantallas más grandes. Así el CSS base es más simple y el móvil descarga menos estilos innecesarios.`],
      k: [`<meta name="viewport" content="width=device-width, initial-scale=1">`, `Mobile first: estilos base para móvil + min-width para crecer.`, `Diseña en una columna y añade columnas cuando haya espacio.`],
      c: `<style>\n  .tarjetas { display: grid; gap: 10px; }\n  .tarjetas div { background: #EEF0FF; padding: 14px; border-radius: 10px; }\n  @media (min-width: 500px) {\n    .tarjetas { grid-template-columns: 1fr 1fr; }\n  }\n</style>\n<div class="tarjetas"><div>Uno</div><div>Dos</div><div>Tres</div><div>Cuatro</div></div>\n<p><small>Por debajo de 500px, una columna; por encima, dos.</small></p>`,
      tip: `en DevTools, el icono del móvil (Ctrl+Shift+M) simula distintos dispositivos.` },
    { n: `7.2`, t: `Media queries`, m: `5 min`,
      b: [`Una media query aplica estilos solo si se cumple una condición: @media (min-width: 768px) { … } se aplica en pantallas de 768px o más. max-width hace lo contrario. Se pueden combinar con and.`,
          `También hay media queries de preferencias del usuario: prefers-color-scheme detecta el modo oscuro, prefers-reduced-motion si prefiere menos animaciones, y hover si el dispositivo tiene ratón. Los puntos de corte deberían salir del contenido (donde el diseño se rompe), no de modelos concretos de móvil.`],
      k: [`@media (min-width: 768px) { … } → 768px o más.`, `Puntos de corte habituales: 600, 768, 1024, 1280px.`, `prefers-color-scheme: dark → modo oscuro del sistema.`, `@media print → estilos para imprimir.`],
      a: [[`(min-width: 768px)`, `Ancho mínimo: tablet y mayores.`], [`(max-width: 600px)`, `Ancho máximo: solo móviles.`], [`(orientation: landscape)`, `Pantalla en horizontal.`], [`(prefers-color-scheme: dark)`, `El usuario usa modo oscuro.`], [`(prefers-reduced-motion: reduce)`, `Prefiere menos animación.`], [`(hover: hover)`, `Dispositivo con ratón.`], [`print`, `Al imprimir.`]], at: `Condiciones de media query`, ah: [`Condición`, `Cuándo se cumple`],
      c: `<style>\n  .caja { padding: 16px; border-radius: 10px; background: #EEF0FF; }\n  @media (max-width: 400px) { .caja { background: #FDE68A; } .caja::after { content: " (pantalla estrecha)"; } }\n  @media (min-width: 401px) { .caja::after { content: " (pantalla ancha)"; } }\n  @media (prefers-color-scheme: dark) { .modo { background: #111827; color: white; } }\n  .modo { padding: 10px; margin-top: 10px; border-radius: 10px; border: 1px solid #ddd; }\n</style>\n<div class="caja">Esta caja cambia según el ancho</div>\n<div class="modo">Esta, según el modo claro u oscuro de tu sistema</div>`,
      tip: `probad a estrechar la vista previa o cambiar vuestro sistema a modo oscuro.` },
    { n: `7.3`, t: `Tamaños fluidos con clamp()`, m: `4 min`,
      b: [`clamp(mínimo, ideal, máximo) devuelve un valor que crece con la pantalla pero nunca baja del mínimo ni supera el máximo. Es perfecto para títulos: font-size: clamp(1.75rem, 5vw, 3rem) se adapta solo, sin media queries.`,
          `min() y max() funcionan igual con dos valores: width: min(100%, 600px) ocupa todo el ancho hasta un máximo de 600px. calc() permite operar mezclando unidades, como calc(100% - 2rem).`],
      k: [`clamp(min, ideal, max) → tamaño fluido con límites.`, `min(100%, 600px) → el menor de los dos.`, `calc(100% - 40px) mezcla unidades.`, `Usa rem en los límites para respetar el zoom del usuario.`],
      a: [[`clamp(a, b, c)`, `b, pero nunca menos que a ni más que c.`], [`min(a, b)`, `El menor de los valores.`], [`max(a, b)`, `El mayor de los valores.`], [`calc()`, `Operaciones: + - * /.`]], at: `Funciones de tamaño`, ah: [`Función`, `Qué devuelve`],
      c: `<style>\n  h1 { font-size: clamp(1.5rem, 8vw, 3rem); margin: 0; }\n  .caja { width: min(100%, 300px); background: #EEF0FF; padding: 10px; border-radius: 10px; }\n  .resta { width: calc(100% - 60px); background: #FBCFE8; padding: 10px; margin-top: 8px; border-radius: 10px; }\n</style>\n<h1>Título fluido</h1>\n<div class="caja">min(100%, 300px)</div>\n<div class="resta">calc(100% - 60px)</div>`,
      tip: `con clamp en los títulos os ahorráis la mayoría de media queries de tipografía.` },
    { n: `7.4`, t: `Imágenes y tablas responsive`, m: `4 min`,
      b: [`Las imágenes necesitan max-width: 100% y height: auto para no salirse de su contenedor. object-fit: cover recorta una imagen para rellenar una caja de tamaño fijo sin deformarla, muy útil en tarjetas con fotos de proporciones distintas.`,
          `Las tablas anchas no caben en móvil: lo más sencillo es envolverlas en un div con overflow-x: auto para que se puedan desplazar horizontalmente.`],
      k: [`img { max-width: 100%; height: auto; }`, `object-fit: cover → rellena sin deformar.`, `object-position elige qué parte se ve.`, `Tablas: contenedor con overflow-x: auto.`],
      a: [[`object-fit: cover`, `Rellena la caja recortando.`], [`object-fit: contain`, `Se ve entera, puede dejar huecos.`], [`object-position`, `Qué zona de la imagen se muestra.`], [`overflow-x: auto`, `Scroll horizontal si no cabe.`]], at: `Contenido adaptable`, ah: [`Propiedad`, `Uso`],
      c: `<style>\n  .fotos { display: grid; grid-template-columns: repeat(3, 1fr); gap: 8px; }\n  .fotos img { width: 100%; height: 90px; object-fit: cover; border-radius: 8px; }\n  .tabla { overflow-x: auto; margin-top: 10px; }\n  table { border-collapse: collapse; min-width: 500px; }\n  td { border: 1px solid #ddd; padding: 6px; }\n</style>\n<div class="fotos">\n  <img src="https://placehold.co/400x200/4F46E5/fff?text=Ancha" alt="">\n  <img src="https://placehold.co/200x400/EC4899/fff?text=Alta" alt="">\n  <img src="https://placehold.co/300x300/0E9F6E/fff?text=Cuadrada" alt="">\n</div>\n<div class="tabla"><table><tr><td>Hora</td><td>Escenario</td><td>Artista</td><td>Género</td><td>Duración</td></tr></table></div>`,
      tip: `fijaos en que las tres fotos tienen proporciones distintas pero ocupan lo mismo.` },
    { n: `7.5`, t: `Container queries`, m: `4 min`,
      b: [`Las media queries miran el tamaño de la ventana; las container queries miran el tamaño del contenedor. Así un componente (una tarjeta) se adapta a donde lo pongas: en horizontal si su caja es ancha y en vertical si es estrecha, esté en la columna principal o en la barra lateral.`,
          `Se declara el contenedor con container-type: inline-size y luego se usa @container (min-width: 400px) { … }. Funcionan en todos los navegadores modernos.`],
      k: [`container-type: inline-size en el padre.`, `@container (min-width: 400px) { … } en los hijos.`, `Ideal para componentes reutilizables.`, `Unidades cqw: % del ancho del contenedor.`],
      c: `<style>\n  .zona { container-type: inline-size; border: 1px dashed #999; padding: 8px; margin-bottom: 10px; }\n  .ancha { width: 100%; } .estrecha { width: 220px; }\n  .card { display: grid; gap: 8px; background: #EEF0FF; padding: 10px; border-radius: 10px; }\n  .card .img { height: 60px; background: #4F46E5; border-radius: 8px; }\n  @container (min-width: 300px) { .card { grid-template-columns: 100px 1fr; } }\n</style>\n<div class="zona ancha"><div class="card"><div class="img"></div><p>En un contenedor ancho: horizontal.</p></div></div>\n<div class="zona estrecha"><div class="card"><div class="img"></div><p>En uno estrecho: vertical.</p></div></div>`,
      tip: `la misma tarjeta, el mismo CSS, dos diseños según dónde esté.` }
  ]},
  { t: `Posicionamiento y transformaciones`, d: `position, z-index, sticky, transform y filtros.`, secciones: [
    { n: `8.1`, t: `position`, m: `6 min`,
      b: [`position cambia cómo se coloca un elemento. static es el valor normal. relative lo desplaza respecto a su posición original sin afectar a los demás. absolute lo saca del flujo y lo coloca respecto al ancestro posicionado más cercano (uno con position distinto de static). fixed lo coloca respecto a la ventana y se queda quieto al hacer scroll.`,
          `Se mueve con top, right, bottom y left (o el atajo inset). El patrón más común: el padre con position: relative y el hijo con position: absolute, por ejemplo para una etiqueta «Nuevo» en la esquina de una tarjeta.`],
      k: [`Padre relative + hijo absolute = colocar dentro del padre.`, `absolute y fixed salen del flujo: los demás ocupan su hueco.`, `fixed se queda fijo en la ventana (botón «volver arriba»).`, `inset: 0 = top, right, bottom y left a 0.`],
      a: [[`static`, `Normal. top/left no hacen nada.`], [`relative`, `Desplazado respecto a su sitio; sigue ocupando su hueco.`], [`absolute`, `Respecto al ancestro posicionado; sale del flujo.`], [`fixed`, `Respecto a la ventana; no se mueve con el scroll.`], [`sticky`, `Normal hasta un punto y luego se queda pegado.`], [`top / right / bottom / left`, `Desplazamiento.`], [`inset`, `Atajo de los cuatro.`]], at: `Valores de position`, ah: [`Valor`, `Comportamiento`],
      c: `<style>\n  .tarjeta { position: relative; width: 200px; padding: 30px 14px 14px; background: #EEF0FF; border-radius: 12px; }\n  .etiqueta { position: absolute; top: 8px; right: 8px; background: crimson; color: white; font-size: 12px; padding: 2px 8px; border-radius: 999px; }\n  .movido { position: relative; left: 20px; background: #FDE68A; display: inline-block; }\n</style>\n<div class="tarjeta"><span class="etiqueta">Nuevo</span>Abono VIP</div>\n<p>Texto <span class="movido">relative + left 20px</span> y sigue el texto.</p>`,
      e: `poner position: absolute en el hijo sin poner position: relative en el padre: el hijo se coloca respecto a toda la página.`,
      tip: `cuando algo absolute aparece donde no esperabais, buscad qué ancestro tiene position.` },
    { n: `8.2`, t: `z-index y capas`, m: `4 min`,
      b: [`Cuando los elementos se solapan, z-index decide cuál queda encima: el valor más alto gana. Solo funciona en elementos posicionados (relative, absolute, fixed, sticky) o en hijos de flex y grid.`,
          `Cada elemento con z-index (y otras propiedades como opacity o transform) crea un «contexto de apilamiento»: sus hijos solo compiten entre ellos. Por eso a veces un z-index: 9999 no consigue salir por encima de otro elemento.`],
      k: [`z-index mayor = más arriba.`, `Necesita position distinto de static (o ser hijo flex/grid).`, `Usa una escala sencilla: 10, 20, 100 (menús, modales…).`, `Un z-index enorme no salta fuera de su contexto de apilamiento.`],
      c: `<style>\n  .capas { position: relative; height: 130px; }\n  .capas div { position: absolute; width: 100px; height: 80px; border-radius: 10px; color: white; padding: 8px; }\n  .a { background: #4F46E5; left: 0; top: 0; z-index: 1; }\n  .b { background: #EC4899; left: 50px; top: 25px; z-index: 3; }\n  .c { background: #0E9F6E; left: 100px; top: 50px; z-index: 2; }\n</style>\n<div class="capas"><div class="a">z 1</div><div class="b">z 3</div><div class="c">z 2</div></div>`,
      tip: `definid variables como --z-menu: 100; --z-modal: 200; para no ir improvisando números.` },
    { n: `8.3`, t: `position: sticky`, m: `3 min`,
      b: [`sticky es una mezcla de relative y fixed: el elemento se comporta normal hasta que, al hacer scroll, llega al umbral indicado (por ejemplo top: 0) y entonces se queda pegado mientras su contenedor siga visible.`,
          `Se usa para cabeceras que se quedan arriba, cabeceras de tabla o índices laterales. Si no funciona, suele ser porque algún ancestro tiene overflow: hidden o porque falta el top.`],
      k: [`position: sticky; top: 0;`, `Se queda pegado dentro de su contenedor.`, `No funciona si un ancestro tiene overflow hidden o auto.`],
      c: `<style>\n  .scroll { height: 150px; overflow: auto; border: 1px solid #ddd; border-radius: 10px; }\n  .cab { position: sticky; top: 0; background: #111827; color: white; padding: 8px; }\n  p { margin: 0; padding: 10px; }\n</style>\n<div class="scroll">\n  <div class="cab">Cabecera pegajosa</div>\n  <p>Haz scroll dentro de esta caja…</p><p>Línea</p><p>Línea</p><p>Línea</p><p>Línea</p><p>Línea</p><p>Final</p>\n</div>`,
      tip: `la cabecera de DevPath usa position: sticky.` },
    { n: `8.4`, t: `transform`, m: `5 min`,
      b: [`transform modifica visualmente un elemento sin afectar al resto del diseño: translate lo mueve, scale lo agranda o encoge, rotate lo gira y skew lo inclina. Se pueden combinar varias funciones separadas por espacios.`,
          `transform-origin cambia el punto desde el que se transforma (por defecto, el centro). Como no recalcula el diseño, transform es la propiedad ideal para animaciones fluidas.`],
      k: [`translate(x, y) mueve; scale(1.1) agranda; rotate(15deg) gira.`, `No mueve a los demás elementos.`, `transform-origin: top left cambia el punto de giro.`, `Centrar con absolute: top 50% left 50% + translate(-50%, -50%).`],
      a: [[`translate(20px, 10px)`, `Desplaza.`], [`scale(1.2)`, `Escala al 120 %.`], [`rotate(45deg)`, `Gira 45 grados.`], [`skew(10deg)`, `Inclina.`], [`transform-origin`, `Punto de referencia de la transformación.`]], at: `Funciones de transform`, ah: [`Función`, `Efecto`],
      c: `<style>\n  .fila { display: flex; gap: 30px; padding: 20px; }\n  .fila div { width: 70px; height: 70px; background: #4F46E5; color: white; display: grid; place-items: center; border-radius: 10px; }\n  .t1 { transform: translate(10px, 10px); }\n  .t2 { transform: scale(1.2); }\n  .t3 { transform: rotate(20deg); }\n  .t4 { transform: skew(-10deg); }\n</style>\n<div class="fila"><div class="t1">mover</div><div class="t2">escalar</div><div class="t3">girar</div><div class="t4">inclinar</div></div>`,
      tip: `transform: translateY(-4px) en :hover es el efecto clásico de tarjeta que «sube».` },
    { n: `8.5`, t: `Filtros y efectos`, m: `3 min`,
      b: [`filter aplica efectos gráficos a un elemento: blur desenfoca, grayscale lo pasa a blanco y negro, brightness y contrast ajustan la imagen, y drop-shadow añade una sombra que respeta la forma (ideal para PNG con transparencia).`,
          `backdrop-filter aplica el efecto a lo que hay detrás del elemento: con un fondo semitransparente y blur se consigue el efecto «cristal esmerilado» de muchas cabeceras modernas.`],
      k: [`filter: grayscale(1) → blanco y negro.`, `filter: blur(4px) → desenfoque.`, `backdrop-filter: blur(8px) → efecto cristal.`, `Se pueden encadenar varios filtros.`],
      c: `<style>\n  .fotos { display: flex; gap: 8px; }\n  .fotos img { width: 100px; border-radius: 8px; }\n  .gris { filter: grayscale(1); }\n  .gris:hover { filter: none; }\n  .blur { filter: blur(3px); }\n  .cristal { position: relative; margin-top: -40px; margin-left: 20px; width: 200px; padding: 10px; background: rgb(255 255 255 / 40%); backdrop-filter: blur(6px); border-radius: 10px; }\n</style>\n<div class="fotos">\n  <img src="https://placehold.co/200x140/EC4899/fff?text=Normal" alt="">\n  <img class="gris" src="https://placehold.co/200x140/4F46E5/fff?text=Gris" alt="">\n  <img class="blur" src="https://placehold.co/200x140/0E9F6E/fff?text=Blur" alt="">\n</div>\n<div class="cristal">Efecto cristal</div>`,
      tip: `pasad el ratón por la foto gris: recupera el color con :hover.` }
  ]},
  { t: `Transiciones y animaciones`, d: `transition, @keyframes, animation y movimiento accesible.`, secciones: [
    { n: `9.1`, t: `Transiciones`, m: `5 min`,
      b: [`transition hace que un cambio de estilo (por ejemplo al pasar el ratón) ocurra de forma gradual en lugar de instantánea. Se indica qué propiedad animar, la duración, la curva de velocidad y, opcionalmente, un retraso.`,
          `Las curvas (timing functions) más usadas son ease (por defecto), ease-in-out, linear y cubic-bezier para curvas personalizadas. Para que la animación vaya fluida, anima solo transform y opacity: el resto de propiedades obliga al navegador a recalcular el diseño en cada fotograma.`],
      k: [`transition: transform .2s ease;`, `La transición se pone en el estado normal, no en :hover.`, `Anima transform y opacity para que vaya fluido.`, `Evita transition: all: anima cosas que no esperas.`],
      a: [[`transition-property`, `Qué propiedad se anima.`], [`transition-duration`, `Cuánto dura (.3s, 300ms).`], [`transition-timing-function`, `ease, linear, ease-in-out, cubic-bezier().`], [`transition-delay`, `Retraso antes de empezar.`], [`transition`, `Atajo: propiedad duración curva retraso.`]], at: `Propiedades de transición`, ah: [`Propiedad`, `Qué controla`],
      c: `<style>\n  .card { width: 200px; padding: 16px; background: white; border: 1px solid #E5E7EB; border-radius: 14px; transition: transform .2s ease, box-shadow .2s ease; }\n  .card:hover { transform: translateY(-6px); box-shadow: 0 14px 30px rgb(79 70 229 / 25%); }\n  .btn { margin-top: 14px; padding: 10px 16px; border: 0; border-radius: 8px; background: #4F46E5; color: white; transition: background-color .3s; }\n  .btn:hover { background: #EC4899; }\n</style>\n<div class="card">Pasa el ratón por esta tarjeta</div>\n<button class="btn">Y por este botón</button>`,
      tip: `entre .15s y .3s es la duración ideal para efectos de interfaz.` },
    { n: `9.2`, t: `@keyframes y animation`, m: `5 min`,
      b: [`Las animaciones con @keyframes definen varios pasos (from/to o porcentajes) y se aplican con la propiedad animation, que no necesita ninguna interacción: empiezan solas al cargar.`,
          `animation indica el nombre, la duración, la curva, el número de repeticiones (infinite para siempre), la dirección (alternate va y vuelve) y el modo de relleno (forwards mantiene el estado final).`],
      k: [`@keyframes nombre { from { … } to { … } }`, `animation: nombre 1s ease-in-out infinite alternate;`, `forwards mantiene el último fotograma.`, `animation-delay escalonado crea efectos en cascada.`],
      a: [[`animation-name`, `Nombre del @keyframes.`], [`animation-duration`, `Duración de un ciclo.`], [`animation-iteration-count`, `Repeticiones: 3, infinite.`], [`animation-direction`, `normal, reverse, alternate.`], [`animation-fill-mode`, `forwards, backwards, both.`], [`animation-play-state`, `running o paused.`]], at: `Propiedades de animación`, ah: [`Propiedad`, `Qué controla`],
      c: `<style>\n  @keyframes latido { from { transform: scale(1); } to { transform: scale(1.15); } }\n  @keyframes girar { to { transform: rotate(360deg); } }\n  @keyframes aparecer { from { opacity: 0; transform: translateY(20px); } to { opacity: 1; transform: none; } }\n  .corazon { display: inline-block; font-size: 40px; animation: latido .6s ease-in-out infinite alternate; }\n  .loader { width: 36px; height: 36px; border: 4px solid #E5E7EB; border-top-color: #4F46E5; border-radius: 50%; animation: girar 1s linear infinite; }\n  .entra { animation: aparecer .6s ease both; }\n  .entra:nth-child(2) { animation-delay: .2s; } .entra:nth-child(3) { animation-delay: .4s; }\n</style>\n<span class="corazon">♥</span>\n<div class="loader"></div>\n<ul><li class="entra">Uno</li><li class="entra">Dos</li><li class="entra">Tres</li></ul>`,
      tip: `modificad el ejemplo (añadid un espacio) para que se recargue y veréis la animación de entrada.` },
    { n: `9.3`, t: `Animaciones accesibles`, m: `3 min`,
      b: [`Algunas personas sufren mareos con el movimiento en pantalla. Los sistemas operativos tienen una opción para reducir el movimiento, y CSS la detecta con la media query prefers-reduced-motion. Respetarla es una buena práctica y forma parte de las pautas de accesibilidad.`,
          `Además, evitad animaciones que parpadeen más de tres veces por segundo y que el contenido importante dependa de una animación para entenderse.`],
      k: [`@media (prefers-reduced-motion: reduce) { … }`, `Desactiva o acorta las animaciones grandes.`, `Nada de parpadeos rápidos.`],
      c: `<style>\n  .flota { animation: flotar 2s ease-in-out infinite alternate; display: inline-block; font-size: 30px; }\n  @keyframes flotar { to { transform: translateY(-14px); } }\n  @media (prefers-reduced-motion: reduce) {\n    *, *::before, *::after { animation-duration: .01ms !important; animation-iteration-count: 1 !important; transition-duration: .01ms !important; }\n  }\n</style>\n<span class="flota">🎈</span>\n<p>Si activas «reducir movimiento» en tu sistema, el globo deja de moverse.</p>`,
      tip: `este bloque de prefers-reduced-motion es de los pocos casos donde !important está justificado.` }
  ]},
  { t: `CSS moderno y buenas prácticas`, d: `Variables, anidamiento, :has, modo oscuro, organización y metodología BEM.`, secciones: [
    { n: `10.1`, t: `Variables (custom properties)`, m: `5 min`,
      b: [`Las variables CSS guardan un valor con un nombre que empieza por dos guiones (--color-primario) y se usan con var(). Se suelen declarar en :root para que estén disponibles en toda la página, y se pueden redefinir dentro de cualquier selector.`,
          `Son la base de los temas: cambiando unas pocas variables cambias los colores de toda la web, por ejemplo para el modo oscuro. var() admite un valor de reserva: var(--radio, 8px).`],
      k: [`:root { --primario: #4F46E5; }`, `color: var(--primario);`, `Se heredan y se pueden redefinir por zonas.`, `Valor de reserva: var(--x, 10px).`],
      c: `<style>\n  :root { --primario: #4F46E5; --fondo: #EEF0FF; --radio: 12px; }\n  .tema-rosa { --primario: #EC4899; --fondo: #FCE7F3; }\n  .caja { background: var(--fondo); border: 2px solid var(--primario); color: var(--primario); border-radius: var(--radio); padding: 12px; margin-bottom: 8px; }\n</style>\n<div class="caja">Usa las variables de :root</div>\n<div class="tema-rosa"><div class="caja">Mismo CSS, variables redefinidas</div></div>`,
      tip: `definid al principio de styles.css vuestra paleta, tipografías y espacios como variables.` },
    { n: `10.2`, t: `Modo oscuro`, m: `4 min`,
      b: [`Con variables y la media query prefers-color-scheme, el modo oscuro se reduce a redefinir los colores. Añadir color-scheme: light dark le dice al navegador que adapte también las barras de desplazamiento y los controles de formulario.`,
          `Si queréis un botón para cambiar el tema manualmente, la idea es la misma: una clase (o un atributo data-theme) en el html que redefine las variables, y JavaScript que la pone o la quita.`],
      k: [`@media (prefers-color-scheme: dark) { :root { … } }`, `color-scheme: light dark adapta los controles nativos.`, `Fondo oscuro no negro puro: #0F172A o #111827.`],
      c: `<style>\n  :root { --bg: #FFFFFF; --texto: #111827; --tarjeta: #F3F4F6; color-scheme: light dark; }\n  @media (prefers-color-scheme: dark) { :root { --bg: #0F172A; --texto: #E5E7EB; --tarjeta: #1E293B; } }\n  body { background: var(--bg); color: var(--texto); }\n  .tarjeta { background: var(--tarjeta); padding: 14px; border-radius: 12px; }\n</style>\n<div class="tarjeta">Esta tarjeta sigue el modo claro u oscuro de tu sistema.</div>\n<input placeholder="Los controles también se adaptan">`,
      tip: `el atributo data-theme="dark" en el html es la forma más común de hacer el botón de cambio.` },
    { n: `10.3`, t: `Selectores modernos: :is, :where, :has y anidamiento`, m: `5 min`,
      b: [`:is() agrupa selectores dentro de otro selector (:is(h1, h2, h3) a) y :where() hace lo mismo pero con especificidad cero, ideal para estilos base fáciles de sobrescribir. :has() es el «selector padre»: .tarjeta:has(img) selecciona las tarjetas que contienen una imagen, y form:has(:invalid) los formularios con algún error.`,
          `El CSS moderno también permite anidar reglas, como en Sass: dentro de .menu { } se puede escribir a { } o &:hover { }. Funciona en todos los navegadores actuales.`],
      k: [`:is(a, b) agrupa; :where() igual pero sin especificidad.`, `:has() selecciona un elemento según lo que contiene.`, `Anidamiento: .card { & h3 { … } &:hover { … } }`],
      c: `<style>\n  .tarjeta { padding: 12px; border: 2px solid #E5E7EB; border-radius: 12px; margin-bottom: 8px; }\n  .tarjeta:has(img) { border-color: #4F46E5; }\n  .tarjeta img { width: 60px; border-radius: 8px; }\n  form:has(input:invalid) button { opacity: .4; }\n  .menu {\n    display: flex; gap: 10px;\n    & a { color: #4F46E5; }\n    & a:hover { color: #EC4899; }\n  }\n</style>\n<div class="tarjeta">Sin imagen</div>\n<div class="tarjeta"><img src="https://placehold.co/80" alt=""> Con imagen (borde lila gracias a :has)</div>\n<form><input type="email" required placeholder="correo"> <button>Enviar</button></form>\n<nav class="menu"><a href="#">Inicio</a><a href="#">Cartel</a></nav>`,
      tip: `escribid un correo válido en el ejemplo: el botón deja de estar apagado gracias a :has.` },
    { n: `10.4`, t: `Organizar el CSS y BEM`, m: `5 min`,
      b: [`En un proyecto que crece, el CSS se vuelve caótico si no hay un orden. Una estructura habitual es: variables y reset al principio, estilos base de etiquetas, componentes (botones, tarjetas…), maquetación de las páginas y utilidades.`,
          `BEM (Bloque, Elemento, Modificador) es una convención de nombres de clase: .tarjeta es el bloque, .tarjeta__titulo un elemento suyo y .tarjeta--destacada una variante. Evita selectores largos y deja claro qué pertenece a qué.`],
      k: [`Orden: variables → reset → base → componentes → layout → utilidades.`, `BEM: .bloque, .bloque__elemento, .bloque--modificador.`, `Selectores cortos de una clase: más fáciles de mantener.`, `Evita ids y !important para dar estilo.`],
      a: [[`.tarjeta`, `Bloque: componente independiente.`], [`.tarjeta__titulo`, `Elemento: parte del bloque.`], [`.tarjeta--destacada`, `Modificador: variante del bloque.`]], at: `Convención BEM`, ah: [`Clase`, `Significado`],
      c: `<style>\n  .tarjeta { padding: 14px; border-radius: 12px; background: #F3F4F6; margin-bottom: 8px; }\n  .tarjeta__titulo { margin: 0 0 4px; font-size: 1.1rem; }\n  .tarjeta__texto { margin: 0; color: #4B5563; }\n  .tarjeta--destacada { background: #4F46E5; }\n  .tarjeta--destacada .tarjeta__titulo, .tarjeta--destacada .tarjeta__texto { color: white; }\n</style>\n<article class="tarjeta"><h3 class="tarjeta__titulo">Entrada de día</h3><p class="tarjeta__texto">39 €</p></article>\n<article class="tarjeta tarjeta--destacada"><h3 class="tarjeta__titulo">Abono</h3><p class="tarjeta__texto">89 €</p></article>`,
      tip: `en proyectos de grupo, acordad la convención de nombres el primer día.` },
    { n: `10.5`, t: `Depurar CSS y frameworks`, m: `4 min`, v: 0,
      b: [`Cuando algo no se ve como esperas, sigue siempre los mismos pasos en DevTools: comprueba que el selector afecta al elemento, mira si la declaración está tachada (otra regla gana), revisa el modelo de caja y busca el ancestro que provoca el problema. Un truco clásico es poner * { outline: 1px solid red } para ver todas las cajas.`,
          `Frameworks como Bootstrap o Tailwind aceleran el trabajo con componentes o clases utilitarias ya hechas, pero conviene dominar antes el CSS puro: sin entenderlo, personalizar un framework es mucho más difícil. Sass es un preprocesador que añade funciones, mixins y archivos parciales.`],
      k: [`Declaración tachada = otra regla gana.`, `* { outline: 1px solid red } muestra todas las cajas.`, `Bootstrap: componentes listos. Tailwind: clases utilitarias.`, `Sass: variables, anidamiento, mixins y parciales.`],
      a: [[`Bootstrap`, `Rejilla y componentes con clases como .btn .card .row.`], [`Tailwind CSS`, `Clases de una propiedad: flex p-4 text-center.`], [`Sass / SCSS`, `Preprocesador que se compila a CSS.`], [`PostCSS / Autoprefixer`, `Añade prefijos para navegadores antiguos.`]], at: `Herramientas del ecosistema`, ah: [`Herramienta`, `Qué aporta`],
      c: `/* Truco de depuración: ver todas las cajas */\n* { outline: 1px solid red; }\n\n/* Bootstrap */\n<button class="btn btn-primary">Comprar</button>\n\n/* Tailwind */\n<button class="bg-indigo-600 text-white px-4 py-2 rounded-lg">Comprar</button>`,
      tip: `antes de entregar, pasad vuestro CSS por el validador del W3C (jigsaw.w3.org/css-validator).` }
  ]}
],
chuleta: [
  ['selector { propiedad: valor; }', 'Estructura de toda regla CSS. Si algo está mal escrito, el navegador lo ignora sin avisar.', 'h1 { color: #4F46E5; }', 'Fundamentos'],
  ['<link rel="stylesheet">', 'Enlaza una hoja de estilos externa desde el head. La forma recomendada.', '<link rel="stylesheet" href="css/styles.css">', 'Fundamentos'],
  ['box-sizing: border-box', 'Hace que width incluya padding y borde. Ponlo a todos los elementos al empezar.', '*, *::before, *::after { box-sizing: border-box; }', 'Fundamentos'],
  ['rem / em / px / %', 'rem: relativo a la letra del html (textos). em: a la del padre. px: fijo. %: del contenedor.', 'h1 { font-size: 2rem; }  /* 32px */', 'Fundamentos'],
  ['!important', 'Fuerza una declaración por encima de todas. Evítalo: complica el mantenimiento.', 'p { color: red !important; }', 'Fundamentos'],
  ['var(--nombre)', 'Lee una variable CSS. Se declaran en :root con dos guiones.', ':root { --primario: #4F46E5; }\n.btn { background: var(--primario); }', 'Fundamentos'],

  ['.clase / #id / etiqueta', 'Selectores básicos. Usa clases para dar estilo; reserva los ids para JavaScript y anclas.', '.tarjeta { padding: 16px; }', 'Selectores'],
  ['A B / A > B', 'Descendiente a cualquier nivel / solo hijo directo.', 'nav a { color: white; }\nul > li { margin: 4px; }', 'Selectores'],
  ['A + B / A ~ B', 'Hermano inmediato / todos los hermanos posteriores.', 'h2 + p { margin-top: 0; }', 'Selectores'],
  ['[atributo="valor"]', 'Selecciona por atributo. ^= empieza, $= termina, *= contiene.', 'a[href$=".pdf"]::after { content: " (PDF)"; }', 'Selectores'],
  [':hover / :focus-visible', 'Ratón encima / enfocado con teclado. Da estilo a los dos para que sea accesible.', '.btn:hover, .btn:focus-visible { background: #3730A3; }', 'Selectores'],
  [':nth-child(n)', 'Elige hijos por posición: even, odd, 3n, 2n+1…', 'tr:nth-child(even) { background: #F3F4F6; }', 'Selectores'],
  [':not() / :has()', ':not excluye; :has selecciona según lo que contiene el elemento.', '.card:has(img) { border-color: #4F46E5; }', 'Selectores'],
  ['::before / ::after', 'Contenido decorativo antes o después. Necesitan content.', '.nuevo::before { content: "★ "; }', 'Selectores'],

  ['color / background-color', 'Color del texto / del fondo. Formatos: nombre, #hex, rgb(), hsl().', 'color: #111827; background: hsl(243 75% 95%);', 'Texto y color'],
  ['font-family', 'Fuente con alternativas, terminando en una familia genérica.', 'font-family: "Inter", Arial, sans-serif;', 'Texto y color'],
  ['font-size / font-weight', 'Tamaño (mejor en rem) / grosor (400 normal, 700 negrita).', 'font-size: 1.125rem; font-weight: 600;', 'Texto y color'],
  ['line-height', 'Interlineado. Sin unidad, entre 1.4 y 1.7 para textos largos.', 'p { line-height: 1.6; }', 'Texto y color'],
  ['text-align / text-decoration', 'Alineación del texto / subrayado. text-decoration: none quita el de los enlaces.', 'a { text-decoration: none; }', 'Texto y color'],
  ['text-transform / letter-spacing', 'Mayúsculas o minúsculas sin tocar el HTML / espacio entre letras.', '.etiqueta { text-transform: uppercase; letter-spacing: 2px; }', 'Texto y color'],
  ['text-overflow: ellipsis', 'Añade «…» a un texto cortado. Necesita overflow hidden y white-space nowrap.', 'overflow: hidden; white-space: nowrap; text-overflow: ellipsis;', 'Texto y color'],
  ['background', 'Atajo de fondo: imagen, posición / tamaño y repetición.', 'background: url(foto.jpg) center / cover no-repeat;', 'Texto y color'],
  ['linear-gradient()', 'Degradado lineal. Se usa como imagen de fondo.', 'background: linear-gradient(135deg, #4F46E5, #EC4899);', 'Texto y color'],

  ['margin / padding', 'Espacio exterior / interior. 1 valor: todos; 2: vertical horizontal; 4: arriba derecha abajo izquierda.', 'padding: 12px 20px; margin: 0 auto;', 'Modelo de caja'],
  ['border / border-radius', 'Borde (grosor estilo color) / esquinas redondeadas. 50 % en un cuadrado = círculo.', 'border: 1px solid #E5E7EB; border-radius: 12px;', 'Modelo de caja'],
  ['box-shadow', 'Sombra de la caja: x y desenfoque extensión color.', 'box-shadow: 0 8px 24px rgb(0 0 0 / 12%);', 'Modelo de caja'],
  ['max-width', 'Ancho máximo. Con margin auto centra el contenido en pantallas grandes.', '.contenedor { max-width: 1200px; margin-inline: auto; }', 'Modelo de caja'],
  ['overflow', 'Qué pasa si el contenido no cabe: visible, hidden, scroll o auto.', '.lista { max-height: 300px; overflow: auto; }', 'Modelo de caja'],
  ['display', 'block, inline, inline-block, flex, grid o none.', '.oculto { display: none; }', 'Modelo de caja'],
  ['aspect-ratio', 'Mantiene una proporción ancho / alto.', '.video { aspect-ratio: 16 / 9; }', 'Modelo de caja'],

  ['display: flex', 'Coloca los hijos en fila (o columna) y permite alinearlos y repartir el espacio.', '.nav { display: flex; gap: 16px; }', 'Flexbox'],
  ['flex-direction', 'Dirección del eje principal: row (fila) o column (columna).', '.menu { flex-direction: column; }', 'Flexbox'],
  ['justify-content', 'Reparto en el eje principal: center, space-between, flex-end…', '.barra { justify-content: space-between; }', 'Flexbox'],
  ['align-items', 'Alineación en el eje cruzado: center, stretch, flex-start…', '.barra { align-items: center; }', 'Flexbox'],
  ['flex-wrap: wrap', 'Permite que los elementos pasen a otra línea si no caben.', '.tarjetas { flex-wrap: wrap; }', 'Flexbox'],
  ['flex: 1', 'En un hijo: crece para repartir el espacio libre a partes iguales.', '.principal { flex: 1; }', 'Flexbox'],
  ['gap', 'Separación entre elementos flex o grid, sin márgenes.', '.fila { gap: 12px; }', 'Flexbox'],
  ['margin-left: auto', 'En un hijo flex: lo empuja al final del contenedor.', '.login { margin-left: auto; }', 'Flexbox'],

  ['display: grid', 'Activa la rejilla en dos dimensiones.', '.galeria { display: grid; }', 'Grid'],
  ['grid-template-columns', 'Define las columnas. fr reparte el espacio libre.', 'grid-template-columns: 250px 1fr;', 'Grid'],
  ['repeat(auto-fit, minmax())', 'Rejilla responsive sin media queries: tantas columnas como quepan.', 'grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));', 'Grid'],
  ['grid-column / grid-row', 'Celdas que ocupa un hijo: inicio / fin o span n.', '.destacada { grid-column: span 2; }', 'Grid'],
  ['grid-template-areas', 'Dibuja la maqueta con nombres; los hijos se asignan con grid-area.', 'grid-template-areas: "cab cab" "menu main";', 'Grid'],
  ['place-items: center', 'Centra el contenido en horizontal y vertical.', '.hero { display: grid; place-items: center; }', 'Grid'],

  ['@media (min-width: 768px)', 'Estilos solo para pantallas de 768px o más (mobile first).', '@media (min-width: 768px) { .grid { grid-template-columns: 1fr 1fr; } }', 'Responsive'],
  ['clamp(min, ideal, max)', 'Tamaño fluido con límites. Ideal para títulos.', 'h1 { font-size: clamp(1.75rem, 5vw, 3rem); }', 'Responsive'],
  ['img { max-width: 100% }', 'Evita que las imágenes se salgan de su contenedor.', 'img { max-width: 100%; height: auto; }', 'Responsive'],
  ['object-fit: cover', 'La imagen rellena su caja recortando, sin deformarse.', '.foto { width: 100%; height: 200px; object-fit: cover; }', 'Responsive'],
  ['@container', 'Estilos según el tamaño del contenedor, no de la ventana.', '.zona { container-type: inline-size; }\n@container (min-width: 400px) { … }', 'Responsive'],
  ['prefers-color-scheme', 'Detecta el modo oscuro del sistema.', '@media (prefers-color-scheme: dark) { :root { --bg: #0F172A; } }', 'Responsive'],

  ['position: relative / absolute', 'Padre relative + hijo absolute = colocar el hijo dentro del padre.', '.card { position: relative; }\n.etiqueta { position: absolute; top: 8px; right: 8px; }', 'Posición y efectos'],
  ['position: fixed / sticky', 'fixed: fijo en la ventana. sticky: se pega al llegar al umbral.', 'header { position: sticky; top: 0; }', 'Posición y efectos'],
  ['z-index', 'Orden de apilamiento: el mayor queda encima. Necesita position.', '.modal { position: fixed; z-index: 100; }', 'Posición y efectos'],
  ['transform', 'Mueve, escala o gira sin afectar al resto del diseño.', '.card:hover { transform: translateY(-4px) scale(1.02); }', 'Posición y efectos'],
  ['transition', 'Anima los cambios de estilo. Ponla en el estado normal.', '.btn { transition: background-color .2s ease; }', 'Posición y efectos'],
  ['@keyframes + animation', 'Animación por pasos que empieza sola.', '@keyframes girar { to { transform: rotate(360deg); } }\n.loader { animation: girar 1s linear infinite; }', 'Posición y efectos'],
  ['filter / backdrop-filter', 'Efectos gráficos al elemento / a lo que hay detrás (efecto cristal).', 'img { filter: grayscale(1); }\nheader { backdrop-filter: blur(8px); }', 'Posición y efectos'],
  ['prefers-reduced-motion', 'Respeta a quien prefiere menos movimiento.', '@media (prefers-reduced-motion: reduce) { * { animation: none !important; } }', 'Posición y efectos']
],
retos: [
  { t: '¿Qué valor de box-sizing hace que width incluya padding y borde?', o: ['content-box', 'border-box', 'padding-box', 'inherit'], ok: 1, why: 'Con border-box la caja mide exactamente lo que indica width.' },
  { t: 'En un contenedor con flex-direction: column, ¿qué propiedad centra los hijos verticalmente?', o: ['align-items', 'justify-content', 'text-align', 'vertical-align'], ok: 1, why: 'En columna, el eje principal es el vertical, y justify-content trabaja en el eje principal.' },
  { t: '¿Qué hace grid-template-columns: repeat(auto-fit, minmax(200px, 1fr))?', o: ['Tres columnas fijas', 'Tantas columnas de al menos 200px como quepan', 'Una columna de 200px', 'Nada sin media queries'], ok: 1, why: 'Crea columnas automáticamente según el espacio, cada una de mínimo 200px.' },
  { t: 'Un hijo con position: absolute se coloca respecto a…', o: ['La ventana', 'Su ancestro posicionado más cercano', 'El hermano anterior', 'El body siempre'], ok: 1, why: 'Por eso el padre suele llevar position: relative.' },
  { t: '¿Cuál es la especificidad de .menu a:hover?', o: ['0-1-1', '0-2-1', '1-0-1', '0-0-3'], ok: 1, why: 'Una clase y una pseudoclase (0-2-0) más una etiqueta (0-0-1).' },
  { t: '¿Qué diferencia hay entre display: none y visibility: hidden?', o: ['Ninguna', 'none quita el elemento; hidden deja su hueco', 'hidden lo borra del HTML', 'none solo funciona en móvil'], ok: 1, why: 'visibility: hidden oculta el elemento pero sigue ocupando su espacio.' },
  { t: '¿Qué hace font-size: clamp(1.5rem, 5vw, 3rem)?', o: ['Siempre 5vw', 'Crece con la pantalla entre 1.5rem y 3rem', 'Siempre 3rem', 'Da error'], ok: 1, why: 'clamp limita el valor ideal entre un mínimo y un máximo.' },
  { t: '¿Qué selector elige las tarjetas que contienen una imagen?', o: ['.card img', '.card > img', '.card:has(img)', 'img .card'], ok: 2, why: ':has() selecciona el elemento según lo que contiene; .card img seleccionaría la imagen.' }
]};
